from pathlib import Path
import re
import sys

root = Path(sys.argv[1]).resolve()
round_no = int(sys.argv[2])


def load(path):
    return (root / path).read_text(encoding="utf-8")


def save(path, text):
    (root / path).write_text(text, encoding="utf-8", newline="\n")


def replace_once(path, old, new):
    text = load(path)
    count = text.count(old)
    if count != 1:
        raise SystemExit(f"{path}: expected one exact match, found {count}\n--- needle ---\n{old}")
    save(path, text.replace(old, new, 1))


def regex_once(path, pattern, replacement, flags=re.S):
    text = load(path)
    updated, count = re.subn(pattern, replacement, text, count=1, flags=flags)
    if count != 1:
        raise SystemExit(f"{path}: expected one regex match, found {count}: {pattern}")
    save(path, updated)


def add_assertion(code):
    path = "tests/third-ten-round-review-tests.php"
    text = load(path)
    marker = "\nif ( $failures ) {"
    if marker not in text:
        raise SystemExit("third review test marker missing")
    save(path, text.replace(marker, "\n" + code.rstrip() + "\n" + marker, 1))


